    "tablet_omar": [
      {"days": "weekday", "from": 0, "to": 10, "at": "chair_k1", "chance": "usually"},
      {"days": "weekday", "from": 10, "to": 12, "at": "kitchen_table_k1", "chance": "sometimes"},
