    {"claim": "Omar's tablet is at the bedroom nightstand during his midday window on weekdays", "target": "tablet_omar", "expect": "nightstand_b1", "days": "weekday", "from": 12, "to": 16},
    {"claim": "Omar's tablet is back at the kitchen chair during his evening gaming on weekdays", "target": "tablet_omar", "expect": "chair_k1", "days": "weekday", "from": 19, "to": 22},
